[ExtensionOf(formStr(SalesTable))]
internal final class SalesTableFormGlobalUnifiedPricing_Extension
{
    private boolean globalUnifiedPricingEnabled = FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance());

}

Method.Source:
[Hookable(false)]
public void init()
{
    next init();

    if (globalUnifiedPricingEnabled)
    {
        this.setFieldVisibility();
    }
}

protected boolean shouldEnableOrderCompletion()
{
    boolean ret = next shouldEnableOrderCompletion();

    FormDataSource salesTableDataSource = SysFormDataSource::findDataSource(this, tableNum(SalesTable));
    SalesTable salesTable = salesTableDataSource.cursor() as SalesTable;

    if (salesTable)
    {
        ret = ret || salesTable.isGUPSalesOrder();
    }

    return ret;
}

protected boolean shouldEnableCompleteButton()
{
    boolean ret = next shouldEnableCompleteButton();

    Common common = this.args().record();
    if (common is SalesTable)
    {
        ret = ret || GUPParameters::isLegacySCMSalesOrder(common);
    }

    return ret;
}

protected boolean shouldOpenOrderSummaryOnLeave()
{
    boolean ret = next shouldOpenOrderSummaryOnLeave();

    FormDataSource salesTableDataSource = SysFormDataSource::findDataSource(this, tableNum(SalesTable));
    SalesTable salesTable = salesTableDataSource.cursor() as SalesTable;

    if (salesTable && salesTable.isGUPSalesOrder())
    {
        this.openOrderSalesTable = null;
        ret = false;
    }

    return ret;
}

protected void recalculatePrice(str logStr, boolean reReadDB)
{
    FormDataSource salesTableDataSource = SysFormDataSource::findDataSource(this, tableNum(SalesTable));
    SalesTable salesTable = salesTableDataSource.cursor() as SalesTable;

    if (salesTable && salesTable.isGUPSalesOrder())
    {
        this.recalculateRetailPricesDiscounts();

        FormControl formControl = this.args().callerFormControl();
        if (reReadDB)
        {
            SalesTable_ds.reRead();
            SalesTable_ds.reReadLines();
        }
    }
}

void mcrOrderEntryModeInit()
{
    next mcrOrderEntryModeInit();
    FormDataSource salesTableDataSource = SysFormDataSource::findDataSource(this, tableNum(SalesTable));
    SalesTable salesTable = salesTableDataSource.cursor() as SalesTable;

    if (salesTable && salesTable.isGUPSalesOrder())
    {
        SalesLine_SalesPrice.enabled(false);
    }
}
